<?php
require_once __DIR__.'/room-ratings.php';
staySmartEnsureRoomRatingsTable($con);
if(empty($_SESSION['delete_review_csrf']))$_SESSION['delete_review_csrf']=bin2hex(random_bytes(32));
$reviewQuery=$con->prepare('SELECT r.*,a.room_name,a.check_in,a.check_out FROM room_reviews r LEFT JOIN archive_bookings a ON a.booking_id=r.booking_id WHERE r.user_id=? ORDER BY r.created_at DESC,r.booking_id DESC');
$reviewQuery->bind_param('i',$reviewUserId);$reviewQuery->execute();$myReviews=$reviewQuery->get_result()->fetch_all(MYSQLI_ASSOC);
$reviewEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<section id="my-reviews" class="my-reviews-section"><div class="my-reviews-heading"><div><p>YOUR ROOM FEEDBACK</p><h2>Your room ratings &amp; reviews</h2></div><a href="mybooking.php#completed-stays-title">Rate a completed stay &rarr;</a></div>
<div class="my-reviews-list"><?php foreach($myReviews as $r): ?><article class="my-review-card"><div class="my-review-person"><img src="<?php echo $reviewEscape(staySmartReviewAvatar($reviewUserId)); ?>" alt="Your profile photo" width="48" height="48"><div><strong><?php echo $reviewEscape($signedInAccount['full_name']?:$signedInAccount['username']); ?></strong><span><?php echo (int)$r['rating']; ?>/5 stars<?php echo $r['is_sample']?' · Sample review':''; ?></span></div><time><?php echo (new DateTimeImmutable($r['created_at']))->format('d M Y'); ?></time></div><h3><?php echo $reviewEscape($r['room_name']??'Your stay'); ?></h3><p><?php echo nl2br($reviewEscape($r['review_text']?:'You left a star rating for this stay.')); ?></p><div class="my-review-actions"><a href="booking-details.php?id=<?php echo (int)$r['booking_id']; ?>">View stay</a><form action="PHP/delete-review.php" method="post" data-confirm="Delete your rating and review? It will also be removed from the homepage."><input type="hidden" name="booking_id" value="<?php echo (int)$r['booking_id']; ?>"><input type="hidden" name="csrf_token" value="<?php echo $reviewEscape($_SESSION['delete_review_csrf']); ?>"><button type="submit">Delete review</button></form></div></article><?php endforeach; ?><?php if(!$myReviews): ?><div class="my-reviews-empty"><h3>No ratings yet</h3><p>Your ratings will appear here after you review a completed stay.</p><a href="mybooking.php">View your bookings &rarr;</a></div><?php endif; ?></div></section>
